__CR('t:fp',[{"t":"함수형 사고","l":[{"t":"핵심 개념","q":[{"t":"choice","k":"개념","q":"같은 입력에는 항상 같은 결과를 내고 부작용이 없는 함수는?","o":["순수 함수","전역 함수","생성자","콜백만"],"a":0,"ex":"순수 함수는 예측 가능하고 테스트하기 쉽습니다."},{"t":"choice","k":"개념","q":"함수를 값처럼 인자로 받거나 돌려줄 수 있는 함수는?","o":["고차 함수","저수준 함수","재귀 함수만","익명 함수만"],"a":0,"ex":"map·filter 가 대표적인 고차 함수입니다."},{"t":"choice","k":"개념","q":"데이터를 바꾸지 않고 새 값을 만드는 성질은?","o":["불변성(immutability)","가변성","전역성","동시성"],"a":0,"ex":"불변성은 버그와 예측 불가를 줄여줍니다."},{"t":"choice","k":"개념","q":"이름 없이 즉석에서 정의하는 함수를 뭐라 하나요?","o":["람다(익명 함수)","메서드","클래스","모듈"],"a":0,"ex":"람다 x => x*2 처럼 간단히 씁니다."}],"th":{"sum":"함수형 사고의 핵심은 부작용 없는 **순수 함수**와 데이터를 바꾸지 않는 **불변성**이며, `map`·`filter`·`reduce` 같은 도구로 데이터를 선언적으로 다룬다.","body":[{"h":"핵심 개념","t":"같은 입력에는 항상 같은 결과를 내고 외부 상태를 바꾸지 않는(부작용 없는) 함수를 순수 함수(pure function)라 한다. 함수를 값처럼 인자로 받거나 반환할 수 있는 함수는 고차 함수(higher-order function)다. 데이터를 직접 바꾸지 않고 항상 새 값을 만들어내는 성질이 불변성(immutability)이고, 이름 없이 즉석에서 정의하는 함수는 람다(lambda, 익명 함수)다."},{"h":"함수형 도구","t":"map은 배열의 각 원소에 함수를 적용해 같은 길이의 새 배열을 만든다. filter는 조건(술어)에 맞는 원소만 남겨 새 배열을 만든다. reduce는 원소들을 누적기로 접어 하나의 값(합계 등)으로 합친다. 세 도구 모두 원본을 바꾸지 않고 새 결과를 반환해 불변성을 지킨다."}],"code":{"c":"const nums = [1, 2, 3, 4];\nnums.map(x => x * 2);        // [2, 4, 6, 8]\nnums.filter(x => x % 2 === 0); // [2, 4]\nnums.reduce((a, x) => a + x, 0); // 10","cap":"map·filter·reduce로 배열을 선언적으로 처리"},"key":["순수 함수 = 같은 입력→같은 출력 + 부작용 없음","고차 함수 = 함수를 인자/반환값으로, 익명 함수 = 람다","map=각 원소 변환, filter=조건 선택, reduce=하나로 합침 (모두 불변)"]}},{"t":"함수형 도구","q":[{"t":"choice","k":"도구","q":"배열의 각 원소를 변환해 새 배열을 만드는 함수형 도구는?","o":["map","for","if","push"],"a":0,"ex":"map 은 원본을 바꾸지 않고 새 배열을 반환합니다."},{"t":"choice","k":"개념","q":"함수형 프로그래밍이 최대한 피하려는 것은?","o":["부작용(side effect)","순수 함수","불변성","재사용"],"a":0,"ex":"외부 상태를 바꾸는 부작용을 줄이는 게 핵심입니다."},{"t":"choice","k":"도구","q":"조건에 맞는 원소만 남겨 새 배열을 만드는 것은?","o":["map","filter","reduce","sort"],"a":1,"ex":"filter 는 조건이 참인 원소만 골라냅니다."},{"t":"choice","k":"도구","q":"배열의 모든 원소를 하나의 값으로 합치는 것은?","o":["map","filter","reduce","find"],"a":2,"ex":"reduce 로 합계·곱 등 누적 결과를 만듭니다."}],"th":{"sum":"함수형 사고의 핵심은 부작용 없는 **순수 함수**와 데이터를 바꾸지 않는 **불변성**이며, `map`·`filter`·`reduce` 같은 도구로 데이터를 선언적으로 다룬다.","body":[{"h":"함수형 도구","t":"map은 배열의 각 원소에 함수를 적용해 같은 길이의 새 배열을 만든다. filter는 조건(술어)에 맞는 원소만 남겨 새 배열을 만든다. reduce는 원소들을 누적기로 접어 하나의 값(합계 등)으로 합친다. 세 도구 모두 원본을 바꾸지 않고 새 결과를 반환해 불변성을 지킨다."},{"h":"핵심 개념","t":"같은 입력에는 항상 같은 결과를 내고 외부 상태를 바꾸지 않는(부작용 없는) 함수를 순수 함수(pure function)라 한다. 함수를 값처럼 인자로 받거나 반환할 수 있는 함수는 고차 함수(higher-order function)다. 데이터를 직접 바꾸지 않고 항상 새 값을 만들어내는 성질이 불변성(immutability)이고, 이름 없이 즉석에서 정의하는 함수는 람다(lambda, 익명 함수)다."}],"code":{"c":"const nums = [1, 2, 3, 4];\nnums.map(x => x * 2);        // [2, 4, 6, 8]\nnums.filter(x => x % 2 === 0); // [2, 4]\nnums.reduce((a, x) => a + x, 0); // 10","cap":"map·filter·reduce로 배열을 선언적으로 처리"},"key":["순수 함수 = 같은 입력→같은 출력 + 부작용 없음","고차 함수 = 함수를 인자/반환값으로, 익명 함수 = 람다","map=각 원소 변환, filter=조건 선택, reduce=하나로 합침 (모두 불변)"]}},{"t":"직접 짜 보기 — 무엇을 할지 대신 무엇인지 적기","th":{"sum":"함수형은 **'어떻게 하라' 대신 '무엇인가' 를 적는 것**이다. 그러면 읽는 사람이 순서를 따라갈 필요가 없다.","body":[{"h":"명령형은 순서, 선언형은 관계","t":"`for` 로 인덱스를 올리며 배열에 넣는 코드는 '어떻게' 를 적는다. `map` 은 '각 원소가 이렇게 바뀐 것' 이라는 관계를 적는다. 뒤쪽이 짧아서 좋은 게 아니라, 중간 상태가 없어서 읽기 쉽다."},{"h":"중간 변수를 없애면 버그가 줄어든다","t":"`i`, `sum`, `tmp` 같은 변수는 잘못 쓸 여지가 있는 자리다. 그 자리가 없으면 그 버그도 없다."},{"h":"작은 함수를 이어 붙인다","t":"거르고 → 바꾸고 → 모으는 세 단계를 각각 이름 붙여 두면, 각 단계를 따로 시험하고 따로 재사용할 수 있다."},{"h":"만능은 아니다","t":"성능이 극한으로 중요한 자리나 한 번에 큰 배열을 여러 번 순회하는 곳에서는 반복문이 나을 수 있다. 기본은 선언형으로 두되, 재 보고 필요할 때 바꾼다."}],"code":{"c":"// 명령형\nlet out = [];\nfor (let i = 0; i < xs.length; i++)\n  if (xs[i] > 0) out.push(xs[i] * 2);\n\n// 선언형\nxs.filter(x => x > 0).map(x => x * 2)","cap":"순서 대신 관계를 적는다"},"key":["'어떻게' 대신 '무엇인가'","중간 변수가 없으면 그 버그도 없다","작은 함수를 이어 붙인다"]},"q":[{"k":"evenSquares · 거르고 바꾸기","cat":"internals","q":"짝수만 남겨 <b>제곱</b>한 배열을 돌려주세요. 원본은 <b>바뀌면 안 됩니다</b>.","src":"function evenSquares(xs) {\n  for (let i = 0; i < xs.length; i++) xs[i] = xs[i] * xs[i];\n  return xs.filter(x => x % 2 === 0);\n}\n","sol":"function evenSquares(xs) {\n  return xs.filter(x => x % 2 === 0).map(x => x * x);\n}\n","ex":"먼저 제곱해 버리면 홀수의 제곱도 홀수라 결과는 우연히 비슷해 보이지만, 원본 배열이 통째로 바뀝니다. 부르는 쪽은 자기 데이터가 달라진 줄 모르고 계속 쓰게 돼요 — `filter`·`map` 은 언제나 새 배열을 만듭니다.","t":"code","run":"js","tests":[{"in":"evenSquares([1,2,3,4])","out":"[4,16]"},{"in":"(() => { const a = [1,2,3]; evenSquares(a); return a; })()","out":"[1,2,3]"},{"in":"evenSquares([])","out":"[]"}],"edge":[{"in":"evenSquares([1,3,5])","out":"[]"},{"in":"evenSquares([0,2])","out":"[0,4]"}]},{"k":"countBy · 세는 일도 관계로","cat":"internals","q":"값마다 <b>몇 번 나왔는지</b>를 담은 객체를 돌려주세요.","src":"function countBy(xs) {\n  const out = {};\n  for (const x of xs) out[x] = 1;\n  return out;\n}\n","sol":"function countBy(xs) {\n  return xs.reduce((acc, x) => { acc[x] = (acc[x] || 0) + 1; return acc; }, {});\n}\n","ex":"`= 1` 로 덮어쓰면 몇 번 나왔든 전부 1 이 됩니다 — 결과의 모양은 맞아서 눈으로 훑으면 지나가기 쉬워요. 세는 일은 '이전 값 + 1' 이라는 관계라, 이전 값을 반드시 읽어야 합니다.","t":"code","run":"js","tests":[{"in":"countBy(['a','b','a'])","out":"{a:2,b:1}"},{"in":"countBy([])","out":"{}"},{"in":"countBy(['x'])","out":"{x:1}"}],"edge":[{"in":"countBy([1,1,1])","out":"{1:3}"},{"in":"countBy(['a','b'])","out":"{a:1,b:1}"}]},{"k":"pipeline · 단계를 이어 붙이기","cat":"internals","q":"함수 배열을 받아 <b>앞에서부터 차례로</b> 적용하는 함수를 돌려주세요.","src":"function pipeline(fns) {\n  return x => fns.reduceRight((v, f) => f(v), x);\n}\n","sol":"function pipeline(fns) {\n  return x => fns.reduce((v, f) => f(v), x);\n}\n","ex":"`reduceRight` 는 뒤에서부터 적용합니다 — 더하고 곱하기와 곱하고 더하기는 결과가 다르니 조용히 틀린 값이 나와요. 파이프라인은 적힌 순서대로 흐른다는 약속이고, 그 약속이 깨지면 읽는 사람이 코드를 못 믿습니다.","t":"code","run":"js","tests":[{"in":"pipeline([x => x + 1, x => x * 10])(0)","out":"10"},{"in":"pipeline([x => x * 10, x => x + 1])(0)","out":"1"},{"in":"pipeline([])(5)","out":"5"}],"edge":[{"in":"pipeline([x => x + 1])(1)","out":"2"},{"in":"pipeline([String, s => s.length])(100)","out":"3"}]}]}]},{"t":"순수함수, 불변성, 그리고 부수효과","l":[{"t":"순수함수란 무엇인가","q":[{"t":"choice","k":"fp-pure-def1","q":"순수함수의 정의로 가장 정확한 것은?","ex":"순수함수의 조건은 참조 투명성(같은 입력 -&gt; 같은 출력)과 관찰 가능한 부수효과의 부재, 이 두 가지뿐이다. 문법이나 인자 개수는 순수성과 아무 관련이 없다. 함수 내부에서 변수를 선언하고 사용하는 것도 얼마든지 허용된다.","o":["같은 입력에 항상 같은 출력을 내고, 관찰 가능한 부수효과가 없는 함수","함수 안에서 변수를 절대 선언하지 않는 함수","인자를 하나만 받는 함수","화살표 함수 문법으로 작성된 모든 함수"],"a":0},{"t":"input","k":"fp-pure-term1","q":"같은 표현식을 그 결과값으로 바꿔 써도 프로그램의 의미가 변하지 않는 성질을 무엇이라 하는가? (한국어 다섯 글자, 예: OO OOO)","ex":"참조 투명성은 f(2)가 항상 4라면 코드 어디서든 f(2)를 4로 치환해도 동작이 같다는 성질이다. 순수함수는 이 성질을 만족하므로 캐싱(메모이제이션)이나 재배치 같은 최적화가 안전해진다. 부수효과가 있으면 치환이 성립하지 않는다.","a":["참조 투명성"]},{"t":"choice","k":"fp-pure-local1","q":"아래 함수 sum은 내부에서 total과 i를 계속 바꾼다. 이 함수의 순수성에 대한 설명으로 옳은 것은?","ex":"total과 i는 호출할 때마다 새로 만들어지고 함수가 끝나면 사라지는 지역 변수라, 그 변경은 외부에서 전혀 관찰되지 않는다. sum은 같은 배열에 항상 같은 합을 돌려주고 nums를 변경하지도 않는다. 따라서 반복문과 재할당을 쓰더라도 순수함수다.","code":"function sum(nums) {\n  let total = 0;\n  for (let i = 0; i &lt; nums.length; i++) {\n    total += nums[i];\n  }\n  return total;\n}","o":["지역 변수를 변경했으므로 부수효과가 있어 불순하다","반복문을 썼으므로 함수형이 아니어서 불순하다","지역 변수 변경은 함수 밖에서 관찰되지 않으므로 순수하다","nums를 읽었으므로 인자 접근 자체가 부수효과라 불순하다"],"a":2},{"t":"choice","k":"fp-pure-impure1","q":"다음 중 순수하지 않은 함수는?","ex":"Date.now()는 호출 시점마다 다른 값을 돌려주므로 같은 인자에 같은 출력을 보장하지 못한다. 나머지 셋은 인자만 보고 새 값을 만들어 반환하며 원본을 건드리지 않는다. 시각이 필요하다면 인자로 주입받아 순수하게 만들 수 있다.","o":["(a, b) =&gt; a * b","(user) =&gt; ({ ...user, active: true })","(xs) =&gt; xs.filter(x =&gt; x &gt; 0)","(name) =&gt; `${name} 님, 지금은 ${Date.now()}`"],"a":3},{"t":"choice","k":"fp-pure-benefit1","q":"순수함수가 테스트하기 쉬운 가장 직접적인 이유는?","ex":"순수함수는 결과가 오직 인자에만 의존하므로, 입력을 만들고 반환값을 비교하는 것만으로 테스트가 끝난다. DB나 전역 상태를 세팅하거나 정리할 필요가 없어 목(mock)도 거의 필요 없다. 속도나 예외 여부는 순수성이 보장해 주는 것이 아니다.","o":["인자만 준비하면 결과를 검증할 수 있고, 외부 상태를 준비하거나 되돌릴 필요가 없다","순수함수는 실행 속도가 항상 더 빠르기 때문이다","순수함수는 예외를 절대 던지지 않기 때문이다","순수함수는 타입 검사를 자동으로 통과하기 때문이다"],"a":0}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"부수효과 다루기","q":[{"t":"choice","k":"fp-side-foreach1","q":"아래 코드에서 doubled에 담기는 값은?","ex":"forEach는 각 원소에 대해 콜백을 실행할 뿐 아무것도 모으지 않고 항상 undefined를 반환한다. 값을 변환해 새 배열을 얻고 싶다면 map을 써야 한다. forEach는 본질적으로 부수효과를 일으키기 위한 메서드다.","code":"const doubled = [1, 2, 3].forEach(n =&gt; n * 2);","o":["[2, 4, 6]","12","undefined","[1, 2, 3]"],"a":2},{"t":"choice","k":"fp-side-list1","q":"다음 중 부수효과가 아닌 것은?","ex":"map은 원본을 그대로 두고 새 배열을 만들어 돌려주므로 함수 밖에서 관찰되는 변화가 없다. 전역 변수 변경, 인자 객체 변경, DOM 조작은 모두 대표적인 부수효과다. 부수효과의 기준은 함수 경계 밖에서 그 변화를 볼 수 있는가이다.","o":["함수 안에서 전역 카운터 변수를 1 증가시킴","인자로 받은 배열에 push로 원소를 추가함","인자로 받은 배열을 map으로 변환해 새 배열을 반환함","document.querySelector로 찾은 요소의 텍스트를 바꿈"],"a":2},{"t":"choice","k":"fp-side-log1","q":"함수 안에 console.log를 한 줄 추가하면 그 함수는 어떻게 되는가?","ex":"console.log는 콘솔이라는 외부 세계에 쓰기를 수행하는 I/O이므로 엄밀히 말하면 함수를 불순하게 만든다. 실무에서는 관대하게 다루기도 하지만, 정의상 부수효과라는 점은 분명히 알아야 한다. 반환값 자체는 그대로 유지된다.","o":["반환값이 바뀌지 않으므로 여전히 순수함수다","출력이라는 I/O 부수효과가 생기므로 엄밀히는 순수하지 않다","로그는 개발용이므로 순수성 판정에서 제외된다","함수가 undefined를 반환하게 된다"],"a":1},{"t":"choice","k":"fp-side-shell1","q":"\"함수형 코어, 명령형 셸\"이라는 설계 원칙이 뜻하는 것은?","ex":"프로그램이 쓸모 있으려면 결국 화면에 그리거나 파일을 써야 하므로 부수효과를 없앨 수는 없다. 대신 결정 로직을 순수함수로 몰아넣고, 그 결과를 실제로 실행하는 얇은 셸만 불순하게 두는 것이다. 그러면 테스트가 필요한 부분의 대부분이 순수해진다.","o":["모든 I/O를 완전히 제거해야 함수형 프로그램이 된다","계산 로직은 순수하게 두고, I/O와 상태 변경은 프로그램 바깥 얇은 층에 모은다","핵심 로직은 클래스로, 나머지는 함수로 작성한다","부수효과가 있는 함수는 반드시 async로 선언해야 한다"],"a":1},{"t":"input","k":"fp-side-arg1","q":"인자로 받은 객체나 배열을 함수 안에서 직접 고치는 것을 무엇이라 부르는가? (한국어 세 글자, 예: OO OO)","ex":"인자로 받은 객체를 고치면 호출한 쪽의 데이터가 몰래 바뀌므로 추적하기 어려운 버그의 원인이 된다. 이는 대표적인 부수효과이며, 스프레드 문법으로 복사본을 만들어 반환하면 피할 수 있다. 인자 변조 또는 인자 변형이라고도 한다.","a":["인자 변경"]},{"t":"choice","k":"fp-side-inject1","q":"아래 함수를 순수하게 만드는 가장 적절한 방법은?","ex":"난수와 현재 시각은 함수 밖의 세계에서 오는 값이므로, 함수 안에서 직접 읽는 한 결과를 예측할 수 없다. 값을 인자로 주입받으면 함수 자체는 순수해지고, 난수를 만드는 불순한 책임은 호출부 경계로 밀려난다. Date.now()도 똑같이 불순하므로 교체는 해결책이 아니다.","code":"function makeId(prefix) {\n  return prefix + Math.random().toString(16).slice(2);\n}","o":["함수 이름 앞에 pure를 붙여 의도를 표시한다","Math.random() 대신 Date.now()를 사용한다","return 값을 const 변수에 먼저 담았다가 반환한다","난수 값을 두 번째 인자로 주입받아 makeId(prefix, rand) 형태로 바꾼다"],"a":3}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"불변성과 안전한 상태 갱신","q":[{"t":"choice","k":"fp-imm-const1","q":"아래 코드의 실행 결과로 옳은 것은?","ex":"const는 user라는 바인딩에 다른 값을 재할당하는 것만 막을 뿐, 그 객체 내부 프로퍼티 변경은 전혀 막지 않는다. 따라서 age는 정상적으로 21이 된다. user = {} 처럼 재할당을 시도했을 때만 TypeError가 난다.","code":"const user = { name: '민지', age: 20 };\nuser.age = 21;\nconsole.log(user.age);","o":["TypeError가 발생한다","21이 출력된다","20이 출력된다","SyntaxError로 실행조차 되지 않는다"],"a":1},{"t":"choice","k":"fp-imm-arr1","q":"배열 메서드 중 원본 배열을 직접 변경하는 것끼리 묶인 것은?","ex":"push, sort, splice, reverse는 원본을 제자리에서 변경하는 메서드다. map, filter, slice, concat 등은 새 배열을 만들어 반환하므로 원본이 안전하다. 정렬을 불변으로 하고 싶다면 [...xs].sort(...) 처럼 복사본을 먼저 만들면 된다.","o":["map, filter, slice","concat, flat, join","push, sort, splice","reduce, find, includes"],"a":2},{"t":"choice","k":"fp-imm-freeze1","q":"Object.freeze에 대한 설명으로 옳은 것은?","ex":"Object.freeze는 얕은 동결이라 obj.a는 못 바꿔도 obj.nested.b는 그대로 바꿀 수 있다. 깊은 불변성이 필요하면 중첩 객체마다 재귀적으로 freeze를 적용해야 한다. const는 재할당만 막을 뿐 동결과는 완전히 다른 개념이다.","o":["객체와 그 안에 중첩된 모든 객체까지 재귀적으로 동결한다","동결된 객체는 읽기도 제한된다","최상위 프로퍼티만 동결하는 얕은 동결이라 중첩 객체는 여전히 변경 가능하다","const로 선언된 객체는 자동으로 동결된다"],"a":2},{"t":"input","k":"fp-imm-copy1","q":"기존 배열을 바꾸지 않고 원소 하나를 덧붙인 새 배열을 만드는 표현을 완성하라. 빈칸에 들어갈 연산자를 답하라. (기호 세 글자) 예: const next = [ ___xs, item];","ex":"전개(spread) 연산자 ...는 기존 배열의 원소를 새 배열 리터럴 안에 펼쳐 넣는다. 그 결과 원본 xs는 그대로 남고 새 배열만 만들어진다. push와 달리 부수효과가 없어 불변 갱신에 적합하다.","a":["..."]},{"t":"choice","k":"fp-imm-update1","q":"불변 방식으로 객체의 한 필드만 갱신한 코드는?","ex":"스프레드 문법은 기존 프로퍼티를 복사한 새 객체를 만들고 age만 덮어쓰므로 원본 user는 그대로 남는다. Object.assign(user, ...)은 첫 인자를 직접 변경하므로 불변이 아니다. Object.assign({}, user, { age: 21 })처럼 빈 객체를 대상으로 삼아야 안전하다.","o":["const next = user; next.age = 21;","const next = { ...user, age: 21 };","const next = Object.assign(user, { age: 21 });","const next = user.age++;"],"a":1},{"t":"choice","k":"fp-imm-nested1","q":"state.user.profile.city만 불변으로 바꾸려 할 때 올바른 코드는?","ex":"중첩 객체를 불변으로 갱신하려면 바꾸려는 값까지 이어지는 경로의 모든 층을 각각 복사해야 한다. 층을 건너뛰면 zip 같은 형제 프로퍼티가 통째로 사라진다. 깊이가 깊어지면 Immer 같은 라이브러리로 이 반복을 줄이기도 한다.","code":"const state = { user: { profile: { city: '서울', zip: '01000' } } };","o":["state.user.profile.city = '부산';","{ ...state, city: '부산' }","{ ...state, user: { profile: { city: '부산' } } }","{ ...state, user: { ...state.user, profile: { ...state.user.profile, city: '부산' } } }"],"a":3}],"th":{"sum":"순수함수는 같은 입력에 항상 같은 출력을 내고 관찰 가능한 부수효과가 없는 함수다. 부수효과를 경계 바깥으로 밀어내고 데이터를 불변으로 다루면 코드는 예측 가능하고 테스트하기 쉬워진다.","body":[{"h":"순수함수의 두 가지 조건","t":"첫째, 참조 투명성이다. 같은 인자를 넣으면 언제 어디서 호출하든 항상 같은 값을 돌려준다. 둘째, 관찰 가능한 부수효과가 없다. 함수 내부에서 지역 변수를 만들고 그 값을 계속 바꾸더라도, 그 변화가 함수 밖에서는 전혀 보이지 않으므로 순수성은 깨지지 않는다."},{"h":"무엇이 부수효과인가","t":"콘솔 출력이나 파일 쓰기 같은 I/O, 전역 변수 변경, DOM 조작, 인자로 받은 객체나 배열의 내용 변경이 대표적인 부수효과다. 현재 시각을 읽는 Date.now()나 Math.random()도 호출할 때마다 결과가 달라지므로 순수하지 않다. 이런 값들은 함수 안에서 직접 읽지 말고 인자로 주입받으면 그 함수는 다시 순수해진다."},{"h":"불변성과 const의 오해","t":"const는 변수 바인딩의 재할당만 막을 뿐, 그 변수가 가리키는 객체의 내부 프로퍼티 변경은 전혀 막지 못한다. Object.freeze는 실제로 프로퍼티 변경을 막지만 얕은 동결이라 중첩된 객체 안쪽까지는 보호하지 못한다. 그래서 상태를 갱신할 때는 원본을 고치는 대신 스프레드 문법 등으로 새 객체나 새 배열을 만들어 돌려주는 방식을 쓴다."}],"code":{"c":"// 불순: 인자로 받은 배열을 직접 변경\nfunction addItemBad(cart, item) {\n  cart.push(item);\n  return cart;\n}\n\n// 순수: 새 배열을 반환, 원본은 그대로\nfunction addItem(cart, item) {\n  return [...cart, item];\n}\n\nconst cart = [{ id: 1 }];\nconst next = addItem(cart, { id: 2 });\nconsole.log(cart.length, next.length); // 1 2","cap":"인자를 변경하는 대신 새 값을 반환하면 호출자는 원본을 계속 신뢰할 수 있다."},"key":["순수함수 = 같은 입력 -> 같은 출력 + 관찰 가능한 부수효과 없음","지역 변수 변경은 외부에서 안 보이므로 순수성을 깨지 않는다","const는 재할당만 막고, Object.freeze는 얕은 동결이다"]}},{"t":"직접 짜 보기 — 밖을 건드리지 않기","th":{"sum":"순수함수는 **같은 입력이면 같은 출력이고, 밖을 건드리지 않는** 함수다.","body":[{"h":"시험하기 쉬워진다","t":"밖에 의존하는 게 없으면 값만 넣어 보면 된다. 데이터베이스도, 시계도, 가짜 객체도 필요 없다 — 테스트가 짧아지는 것은 결과일 뿐이고, 진짜 이득은 '이 함수만 보면 안다' 는 점이다."},{"h":"부수효과는 밖으로 몰아 둔다","t":"없앨 수는 없다. 파일도 쓰고 화면도 그려야 한다. 대신 계산은 순수하게 두고, 효과는 가장자리에서 한 번에 처리하면 대부분의 코드가 시험 가능해진다."},{"h":"불변성은 복사로 만든다","t":"배열을 바꾸는 대신 새 배열을 만든다. `push` 대신 전개 연산자, `sort` 대신 복사 후 정렬 — `sort` 와 `reverse` 는 원본을 바꾸는 대표적인 함정이다."},{"h":"숨은 입력을 조심한다","t":"`Date.now()` 나 전역 설정을 함수 안에서 읽으면, 같은 인자에도 결과가 달라진다. 그런 값은 인자로 받는다 — 그것만으로 함수가 순수해진다."}],"code":{"c":"// 원본을 바꾼다\narr.sort();  arr.reverse();  arr.push(x);\n\n// 새로 만든다\n[...arr].sort();  [...arr].reverse();  [...arr, x];\n\n// 숨은 입력을 인자로\nfunction expired(t, now) { return t < now; }","cap":"복사하면 밖이 안 바뀐다"},"key":["같은 입력 → 같은 출력","`sort`·`reverse` 는 원본을 바꾼다","숨은 입력은 인자로 받는다"]},"q":[{"k":"sortedCopy · 정렬해도 원본은 그대로","cat":"internals","q":"오름차순으로 정렬한 <b>새 배열</b>을 돌려주세요. 원본은 <b>그대로</b>여야 합니다.","src":"function sortedCopy(xs) {\n  return xs.sort((a, b) => a - b);\n}\n","sol":"function sortedCopy(xs) {\n  return [...xs].sort((a, b) => a - b);\n}\n","ex":"`sort` 는 새 배열을 주는 것처럼 보이지만 **원본을 정렬하고 그것을 돌려줍니다**. 반환값만 확인하면 통과해서, 화면 목록이 원래 순서를 잃은 뒤에야 발견돼요. 앞에 `[...xs]` 하나면 끝납니다.","t":"code","run":"js","tests":[{"in":"sortedCopy([3,1,2])","out":"[1,2,3]"},{"in":"(() => { const a = [3,1,2]; sortedCopy(a); return a; })()","out":"[3,1,2]"},{"in":"sortedCopy([])","out":"[]"}],"edge":[{"in":"sortedCopy([10,9])","out":"[9,10]"},{"in":"(() => { const a = [2,1]; const b = sortedCopy(a); return a[0]; })()","out":"2"}]},{"k":"isExpired · 시계를 인자로 받기","cat":"internals","q":"만료 시각과 <b>현재 시각</b>을 받아 만료됐으면 true 를 돌려주세요.","src":"function isExpired(t) {\n  return t < Date.now();\n}\n","sol":"function isExpired(t, now) {\n  return t < now;\n}\n","ex":"함수 안에서 시계를 읽으면 같은 인자에도 결과가 달라집니다 — '어제는 통과했는데 오늘은 실패하는 테스트' 의 정체예요. 시간을 인자로 받으면 만료 직전·직후를 마음대로 시험할 수 있습니다.","t":"code","run":"js","tests":[{"in":"isExpired(100, 200)","out":"true"},{"in":"isExpired(300, 200)","out":"false"},{"in":"isExpired(200, 200)","out":"false"}],"edge":[{"in":"isExpired(0, 1)","out":"true"},{"in":"isExpired(1, 1)","out":"false"}]},{"k":"addItem · 새 상태를 만들어 돌려주기","cat":"internals","q":"장바구니 객체 <code>{items: [...]}</code> 에 항목을 더한 <b>새 객체</b>를 돌려주세요. 원본은 그대로입니다.","src":"function addItem(cart, item) {\n  cart.items.push(item);\n  return cart;\n}\n","sol":"function addItem(cart, item) {\n  return { ...cart, items: [...cart.items, item] };\n}\n","ex":"원본을 바꿔서 돌려주면 새 객체가 아니라 **같은 객체**입니다. 이전 상태와 견줘 화면을 다시 그리는 프레임워크는 '안 바뀌었다' 고 판단해 갱신을 건너뛰어요 — 리액트에서 '상태를 바꿨는데 화면이 그대로' 인 사고의 대부분이 이것입니다.","t":"code","run":"js","tests":[{"in":"addItem({items:['a']}, 'b')","out":"{items:['a','b']}"},{"in":"(() => { const c = {items:['a']}; addItem(c, 'b'); return c.items; })()","out":"['a']"},{"in":"addItem({items:[]}, 'x')","out":"{items:['x']}"}],"edge":[{"in":"(() => { const c = {items:[]}; const d = addItem(c,'x'); return c === d; })()","out":"false"},{"in":"addItem({items:['a'], id: 1}, 'b')","out":"{items:['a','b'], id: 1}"}]}]}]},{"t":"고차함수와 함수 합성","l":[{"t":"고차함수의 개념","q":[{"t":"choice","k":"fp-hof-def1","q":"고차함수(higher-order function)의 정의는?","ex":"고차함수는 함수를 값처럼 다루는 함수로, 인자로 받거나 반환값으로 내놓으면 해당한다. map, filter, setTimeout, 함수를 만들어 주는 팩토리가 모두 여기에 속한다. 인자 개수나 재귀 여부는 기준이 아니다.","o":["다른 함수를 인자로 받거나 함수를 반환하는 함수","재귀 호출을 사용하는 모든 함수","인자가 세 개 이상인 함수","클래스 메서드로 정의된 함수"],"a":0},{"t":"input","k":"fp-hof-closure1","q":"함수가 자신이 정의된 위치의 변수(예: factor)를 계속 기억하는 성질 또는 그런 함수를 무엇이라 하는가? (한국어 세 글자)","ex":"클로저는 함수가 만들어질 때의 렉시컬 환경을 함께 붙들고 다니는 구조다. makeMultiplier(3)이 반환한 함수는 호출이 끝난 뒤에도 factor가 3이라는 사실을 기억한다. 커링과 부분적용이 동작하는 근본 원리이기도 하다.","a":["클로저"]},{"t":"choice","k":"fp-hof-return1","q":"아래 makeMultiplier에 대한 설명으로 옳은 것은?","ex":"makeMultiplier는 n =&gt; n * factor라는 함수를 반환하므로 고차함수의 조건을 만족한다. 반환된 함수는 클로저로 factor 값을 계속 기억하므로 triple(5)는 15가 된다. 반대로 triple 자체는 숫자를 받아 숫자를 돌려주는 평범한 함수다.","code":"const makeMultiplier = factor =&gt; n =&gt; n * factor;\nconst triple = makeMultiplier(3);\nconsole.log(triple(5));","o":["makeMultiplier는 고차함수가 아니고 triple만 고차함수다","triple(5)는 3을 출력한다","makeMultiplier는 함수를 반환하므로 고차함수이고, triple(5)는 15다","factor는 makeMultiplier 호출이 끝나면 사라져 triple 호출 시 undefined가 된다"],"a":2},{"t":"choice","k":"fp-hof-firstclass1","q":"일급 함수(first-class function)라는 말의 의미는?","ex":"일급이란 그 언어에서 값과 똑같은 대우를 받는다는 뜻이다. 함수를 변수에 담고, 배열에 넣고, 인자로 넘기고, 반환할 수 있으면 일급 함수다. 이 성질이 있어야 고차함수가 성립한다.","o":["함수가 프로그램에서 가장 먼저 실행된다는 뜻이다","함수가 변수에 담기고 인자로 전달되고 반환값이 될 수 있다는 뜻이다","함수가 클래스보다 우선순위가 높다는 뜻이다","함수 선언이 호이스팅된다는 뜻이다"],"a":1},{"t":"choice","k":"fp-hof-callback1","q":"고차함수를 사용해 반복 로직을 추상화했을 때 얻는 이점으로 가장 적절한 것은?","ex":"map이나 filter는 순회와 인덱스 관리라는 반복적인 뼈대를 숨기고, 각 원소에 대해 무엇을 할지만 콜백으로 표현하게 해 준다. 그 결과 코드의 의도가 이름으로 드러나고 실수도 줄어든다. 성능이 무조건 좋아지거나 순수성이 보장되는 것은 아니다.","o":["실행 속도가 for 문보다 항상 빨라진다","인덱스 관리 같은 반복의 뼈대를 감추고 '무엇을 할지'만 드러내 의도가 명확해진다","메모리를 전혀 사용하지 않게 된다","모든 함수가 자동으로 순수해진다"],"a":1}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."},{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"map / filter / reduce","q":[{"t":"choice","k":"fp-arr-empty1","q":"아래 코드의 실행 결과는?","ex":"초기값 없이 reduce를 호출하면 첫 원소가 초기 누적값이 되는데, 빈 배열에는 첫 원소가 없어 'Reduce of empty array with no initial value' TypeError가 난다. [].reduce((a, b) =&gt; a + b, 0)처럼 초기값을 주면 0이 안전하게 반환된다. 초기값을 명시하는 습관이 중요한 이유다.","code":"[].reduce((a, b) =&gt; a + b);","o":["0을 반환한다","undefined를 반환한다","NaN을 반환한다","TypeError가 발생한다"],"a":3},{"t":"choice","k":"fp-arr-chain1","q":"아래 코드에서 result의 값은?","ex":"filter가 홀수 [1, 3, 5]를 남기고, map이 [10, 30, 50]으로 바꾸고, reduce가 초기값 0부터 더해 90이 된다. 각 단계가 새 배열을 만들기 때문에 원본 배열은 그대로 유지된다. 이런 체이닝이 전형적인 데이터 변환 파이프라인이다.","code":"const result = [1, 2, 3, 4, 5]\n  .filter(n =&gt; n % 2 === 1)\n  .map(n =&gt; n * 10)\n  .reduce((acc, n) =&gt; acc + n, 0);","o":["90","150","60","30"],"a":0},{"t":"choice","k":"fp-arr-map1","q":"map에 대한 설명으로 옳은 것은?","ex":"map은 각 원소에 콜백을 적용한 결과를 모아 새 배열을 만들며 원본은 전혀 건드리지 않는다. 길이는 항상 원본과 같다. 길이를 줄이는 것은 filter, undefined를 반환하는 것은 forEach다.","o":["원본 배열의 각 원소를 제자리에서 변경한다","조건에 맞는 원소만 남겨 길이가 줄어든 배열을 만든다","원본을 바꾸지 않고 같은 길이의 새 배열을 반환한다","항상 undefined를 반환한다"],"a":2},{"t":"choice","k":"fp-arr-reduce1","q":"reduce에 대한 설명으로 옳은 것은?","ex":"reduce는 폴드(fold)라 불리는 일반적인 접기 연산으로, 누적값의 타입에 제한이 없다. 배열을 객체로 그룹핑하거나 문자열로 이어붙이는 것도 전부 reduce로 표현할 수 있다. map과 filter도 사실 reduce로 구현할 수 있다.","o":["결과 타입은 숫자여야 하며 합계나 곱만 계산할 수 있다","누적값과 원소를 접어 나가며 객체, 배열, 문자열 등 임의의 타입을 만들 수 있다","원본 배열의 길이를 항상 유지한다","콜백이 false를 반환하면 순회를 중단한다"],"a":1},{"t":"input","k":"fp-arr-foreach1","q":"[1, 2, 3].forEach(n =&gt; n * 2)의 반환값은 무엇인가? (소문자 영어 한 단어)","ex":"forEach는 콜백을 실행만 하고 결과를 수집하지 않으므로 언제나 undefined를 반환한다. 그래서 체이닝을 이어갈 수 없고, 변환 결과가 필요하면 map을 써야 한다. forEach는 부수효과를 일으키려는 목적일 때만 적합하다.","a":["undefined"]},{"t":"choice","k":"fp-arr-groupby1","q":"reduce로 배열을 카테고리별 객체로 묶을 때 초기값으로 가장 적절한 것은?","ex":"최종 결과가 카테고리를 키로 갖는 객체이므로 누적값의 초기 형태도 빈 객체 {}여야 한다. reduce의 초기값은 항상 만들고자 하는 결과 타입의 '비어 있는 값'으로 두면 된다. null을 주면 acc[key] 접근에서 바로 오류가 난다.","code":"items.reduce((acc, item) =&gt; {\n  const key = item.category;\n  return { ...acc, [key]: [...(acc[key] ?? []), item] };\n}, ???);","o":["0","[]","{}","null"],"a":2}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."},{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"함수 합성과 파이프라인","q":[{"t":"choice","k":"fp-comp-pipe1","q":"아래 코드의 출력은?","ex":"pipe는 왼쪽부터 적용하므로 3에 inc를 적용해 4, 다시 double을 적용해 8이 된다. 같은 함수들을 compose(inc, double)(3)으로 묶으면 double이 먼저 적용돼 7이 나온다. 방향이 다르면 값도 다르다는 점이 핵심이다.","code":"const pipe = (...fns) =&gt; x =&gt; fns.reduce((acc, f) =&gt; f(acc), x);\nconst inc = n =&gt; n + 1;\nconst double = n =&gt; n * 2;\nconsole.log(pipe(inc, double)(3));","o":["7","8","6","9"],"a":1},{"t":"choice","k":"fp-comp-id1","q":"함수 합성의 항등원 역할을 하는 함수는?","ex":"항등함수 x =&gt; x는 받은 값을 그대로 돌려주므로 어떤 함수와 합성해도 그 함수를 바꾸지 않는다. 그래서 compose(f, id) === f 라는 항등원 법칙이 성립한다. 값을 버리거나 바꾸는 다른 보기들은 이 성질을 만족하지 않는다.","o":["() =&gt; {}","x =&gt; null","x =&gt; x","x =&gt; !x"],"a":2},{"t":"choice","k":"fp-comp-unary1","q":"함수들을 파이프라인으로 매끄럽게 이으려면 각 단계 함수가 갖추면 좋은 형태는?","ex":"파이프라인은 앞 함수의 반환값을 그대로 뒤 함수의 유일한 인자로 넘기므로, 단항 함수여야 자연스럽게 연결된다. 인자가 여러 개인 함수는 커링이나 부분적용으로 단항으로 만들어 끼워 넣는다. 아무것도 반환하지 않으면 다음 단계로 넘길 값이 없다.","o":["인자를 하나 받고 값을 하나 반환하는 단항 함수","인자를 두 개 이상 받는 함수","아무 값도 반환하지 않는 함수","전역 변수를 갱신하는 함수"],"a":0},{"t":"choice","k":"fp-comp-order1","q":"compose(f, g)(x)와 같은 의미의 표현은?","ex":"compose는 수학의 합성 표기 f∘g를 따라 오른쪽 함수부터 적용하므로 compose(f, g)(x)는 f(g(x))다. 왼쪽부터 읽히는 순서를 원한다면 pipe(g, f)(x)를 쓰면 같은 결과를 얻는다. 순서를 헷갈리면 결과가 완전히 달라진다.","o":["g(f(x))","f(g(x))","f(x) + g(x)","f(x) 다음에 g(x)를 각각 따로 호출한 것"],"a":1},{"t":"input","k":"fp-comp-impl1","q":"compose를 배열 메서드 하나로 구현할 때 오른쪽부터 접기 위해 사용하는 메서드 이름은? (영어, 예: someMethod)","ex":"reduceRight는 배열을 오른쪽 끝에서 왼쪽으로 접어 나가므로 compose의 적용 순서와 맞는다. 반대로 pipe는 왼쪽부터 접는 reduce로 구현한다. 두 구현은 순회 방향만 다르고 구조는 같다.","a":["reduceRight"]},{"t":"choice","k":"fp-comp-assoc1","q":"함수 합성이 만족하는 성질로 옳은 것은?","ex":"합성은 결합법칙을 만족하므로 어떻게 묶어 그룹핑해도 결과 함수는 동일하다. 또 항등함수 id = x =&gt; x가 항등원이라 compose(f, id)와 compose(id, f)는 모두 f와 같다. 반면 교환법칙은 성립하지 않아 순서를 바꾸면 결과가 달라진다.","o":["교환법칙을 만족해 compose(f, g)와 compose(g, f)는 항상 같다","결합법칙을 만족해 compose(compose(f, g), h)와 compose(f, compose(g, h))가 같다","항등원이 존재하지 않는다","합성 결과는 항상 순수하지 않은 함수가 된다"],"a":1}],"th":{"sum":"고차함수는 함수를 인자로 받거나 함수를 반환하는 함수이며, map/filter/reduce가 대표적인 예다. 작은 순수함수들을 합성해 파이프라인으로 잇는 것이 함수형 설계의 핵심 기법이다.","body":[{"h":"합성과 파이프라인","t":"compose(f, g)(x)는 f(g(x))와 같아서 오른쪽 함수부터 적용되고, pipe(f, g)(x)는 g(f(x))로 왼쪽부터 적용된다. 합성은 결합법칙을 만족하므로 어디서 묶어도 결과가 같고, 아무것도 하지 않는 항등함수 x => x는 합성의 항등원 역할을 한다. 이 성질 덕분에 작은 함수들을 자유롭게 묶어 재사용할 수 있다."},{"h":"고차함수의 정의","t":"함수를 값처럼 인자로 넘기거나 결과로 돌려줄 수 있을 때 그 함수를 일급 함수라 하고, 그런 함수를 받거나 반환하는 함수를 고차함수라 부른다. setTimeout처럼 콜백을 받는 것도, 함수를 만들어 반환하는 팩토리도 모두 고차함수다. 덕분에 반복 구조는 라이브러리에 맡기고 우리는 각 원소에 무엇을 할지만 표현하면 된다."},{"h":"map, filter, reduce","t":"map은 각 원소를 변환해 같은 길이의 새 배열을, filter는 조건을 만족하는 원소만 골라 새 배열을 만든다. 둘 다 원본을 변경하지 않는다. reduce는 누적값과 원소를 접어 나가며 임의의 타입을 만들 수 있어서 숫자뿐 아니라 객체, 배열, 문자열도 결과가 될 수 있다. 다만 초기값 없이 빈 배열에 reduce를 호출하면 TypeError가 발생한다."}],"code":{"c":"const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => x => fns.reduce((acc, f) => f(acc), x);\n\nconst double = n => n * 2;\nconst inc = n => n + 1;\n\nconsole.log(compose(double, inc)(3)); // inc 먼저 -> 8\nconsole.log(pipe(double, inc)(3));    // double 먼저 -> 7","cap":"compose는 오른쪽부터, pipe는 왼쪽부터 적용된다."},"key":["고차함수 = 함수를 인자로 받거나 함수를 반환하는 함수","map/filter는 새 배열을 반환하고 forEach는 undefined를 반환한다","compose(f, g)(x) === f(g(x)), pipe는 반대 순서"]}},{"t":"직접 짜 보기 — 함수를 받고 함수를 돌려주기","th":{"sum":"고차함수는 **함수를 값처럼 다루는 함수**다. 그래서 '무엇을 할지' 를 인자로 넘길 수 있다.","body":[{"h":"동작을 인자로 넘긴다","t":"정렬 기준, 거를 조건, 바꾸는 방법을 함수로 받으면 하나의 틀로 온갖 경우를 다룰 수 있다. `sort(비교함수)` 가 바로 그것이다."},{"h":"reduce 는 나머지를 다 만든다","t":"`map` 도 `filter` 도 `reduce` 로 쓸 수 있다. 초기값과 '한 걸음' 만 정하면 나머지는 같은 모양이다 — 초기값을 빠뜨리면 빈 배열에서 터진다."},{"h":"합성은 이어 붙이기","t":"`compose(f, g)(x)` 는 `f(g(x))` 다. 작은 함수 여럿을 이름 붙여 두고 필요할 때 이어 붙이면, 새 조합을 만드는 데 새 코드가 거의 안 든다."},{"h":"이름을 붙이면 읽힌다","t":"`xs.filter(x => x.age >= 19)` 보다 `xs.filter(isAdult)` 가 낫다. 조건에 이름을 주는 것만으로 주석이 필요 없어진다."}],"code":{"c":"const compose = (f, g) => x => f(g(x));\nconst pipe = (...fns) => x => fns.reduce((v, f) => f(v), x);\n\nxs.reduce((acc, x) => acc + x, 0);   // 초기값 필수","cap":"함수도 값이다"},"key":["동작을 인자로 넘긴다","`reduce` 는 초기값을 준다","조건에 이름을 붙인다"]},"q":[{"k":"sumOf · 무엇을 더할지 넘겨받기","cat":"internals","q":"배열과 <b>값을 꺼내는 함수</b>를 받아 그 값들의 합을 돌려주세요. 빈 배열이면 0 입니다.","src":"function sumOf(xs, f) {\n  return xs.map(f).reduce((a, b) => a + b);\n}\n","sol":"function sumOf(xs, f) {\n  return xs.reduce((acc, x) => acc + f(x), 0);\n}\n","ex":"초기값 없는 `reduce` 는 빈 배열에서 예외를 던집니다 — 목록이 비는 것은 예외적인 상황이 아니라 매일 일어나는 일이에요. 초기값 `0` 하나가 그 경계를 없앱니다.","t":"code","run":"js","tests":[{"in":"sumOf([{n:1},{n:2}], o => o.n)","out":"3"},{"in":"sumOf([], o => o.n)","out":"0"},{"in":"sumOf([1,2,3], x => x * 2)","out":"12"}],"edge":[{"in":"sumOf([{n:5}], o => o.n)","out":"5"},{"in":"sumOf([0,0], x => x)","out":"0"}]},{"k":"compose2 · 두 함수를 이어 붙이기","cat":"internals","q":"<code>compose2(f, g)(x)</code> 가 <code>f(g(x))</code> 가 되게 만드세요.","src":"function compose2(f, g) {\n  return x => g(f(x));\n}\n","sol":"function compose2(f, g) {\n  return x => f(g(x));\n}\n","ex":"`compose` 는 수학의 합성 표기(f∘g)를 따라 **오른쪽부터** 적용합니다. 왼쪽부터 하고 싶으면 그건 `pipe` 예요 — 이름이 다른 이유가 순서라서, 둘을 섞으면 결과가 조용히 뒤집힙니다.","t":"code","run":"js","tests":[{"in":"compose2(x => x + 1, x => x * 10)(1)","out":"11"},{"in":"compose2(x => x * 10, x => x + 1)(1)","out":"20"},{"in":"compose2(x => x, x => x)(5)","out":"5"}],"edge":[{"in":"compose2(s => s.length, n => String(n))(1000)","out":"4"},{"in":"compose2(x => x - 1, x => x - 1)(10)","out":"8"}]},{"k":"byKey · 정렬 기준을 만들어 주기","cat":"internals","q":"키 이름을 받아 <b>그 키로 오름차순 비교하는 함수</b>를 돌려주세요. 정렬에 바로 넘길 수 있어야 합니다.","src":"function byKey(k) {\n  return (a, b) => a[k] > b[k];\n}\n","sol":"function byKey(k) {\n  return (a, b) => (a[k] < b[k] ? -1 : a[k] > b[k] ? 1 : 0);\n}\n","ex":"비교 함수는 음수·0·양수를 돌려줘야 합니다. `true`/`false` 를 주면 각각 1과 0으로 읽혀 '작다' 를 표현할 방법이 없어져요 — 원소가 적으면 우연히 맞기도 해서 더 나쁩니다.","t":"code","run":"js","tests":[{"in":"[{n:3},{n:1},{n:2}].sort(byKey('n')).map(o => o.n)","out":"[1,2,3]"},{"in":"byKey('n')({n:1},{n:2})","out":"-1"},{"in":"byKey('n')({n:2},{n:2})","out":"0"}],"edge":[{"in":"byKey('n')({n:2},{n:1})","out":"1"},{"in":"[{s:'b'},{s:'a'}].sort(byKey('s')).map(o => o.s)","out":"['a','b']"}]}]}]},{"t":"커링, 부분적용, 대수적 데이터 타입","l":[{"t":"커링","q":[{"t":"choice","k":"fp-curry-call1","q":"아래 코드에서 add(1)(2)(3)의 값은?","ex":"add(1)은 b를 기다리는 함수를, add(1)(2)는 c를 기다리는 함수를 돌려주고, 마지막 (3)에서 비로소 1 + 2 + 3이 계산된다. 각 단계는 클로저로 앞선 인자를 기억한다. 이것이 전형적인 커리된 함수의 호출 방식이다.","code":"const add = a =&gt; b =&gt; c =&gt; a + b + c;","o":["6","1","[1, 2, 3]","TypeError"],"a":0},{"t":"choice","k":"fp-curry-def1","q":"커링(currying)의 정의로 옳은 것은?","ex":"커링은 f(a, b, c)를 f(a)(b)(c) 형태로, 각 단계가 인자 하나만 받는 단항 함수의 연쇄가 되도록 바꾸는 구조적 변환이다. 인자 순서를 바꾸는 것은 flip, 결과 캐싱은 메모이제이션, 함수를 잇는 것은 합성이다. 이름이 비슷해 보이는 개념들과 구분해야 한다.","o":["함수의 인자 순서를 뒤집는 변환","n개의 인자를 받는 함수를 한 번에 인자 하나씩 받는 함수들의 연쇄로 바꾸는 변환","함수 호출 결과를 캐싱해 재사용하는 기법","여러 함수를 하나로 합치는 변환"],"a":1},{"t":"input","k":"fp-curry-arity1","q":"커링을 거친 각 단계의 함수는 인자를 몇 개 받는가? (숫자로)","ex":"커링의 정의상 각 단계는 인자를 정확히 하나만 받는 단항 함수다. 마지막 인자가 들어왔을 때 비로소 최종 값이 계산된다. 여러 인자를 한 번에 받는 형태는 커링이 아니라 부분적용에 가깝다.","a":["1"]},{"t":"choice","k":"fp-curry-partialcall1","q":"커리된 함수 add = a =&gt; b =&gt; c =&gt; a + b + c 에서 add(1, 2, 3)을 호출하면?","ex":"커리된 함수의 첫 단계는 매개변수 a 하나만 선언하고 있으므로 나머지 인자 2와 3은 그냥 버려진다. 결과는 여전히 b를 기다리는 함수이며 오류는 발생하지 않는다. 이것이 커링과 일반 다항 함수의 호출 규약이 다르다는 증거다.","o":["6이 반환된다","여분의 인자는 무시되고 b를 기다리는 함수가 반환된다","인자 개수 불일치로 TypeError가 난다","NaN이 반환된다"],"a":1},{"t":"choice","k":"fp-curry-why1","q":"커링이 함수 파이프라인과 잘 어울리는 이유는?","ex":"pipe나 compose는 단항 함수를 이어 붙이므로, 커링으로 설정값을 먼저 넣어 두면 데이터만 받는 단항 함수가 남아 그대로 끼워 넣을 수 있다. 예를 들어 map(fn)을 미리 만들어 두고 배열만 흘려보내는 식이다. 순수성이나 타입 검사와는 무관하다.","o":["커링된 함수는 항상 순수하기 때문이다","커링은 함수 호출 비용을 줄여 주기 때문이다","설정값을 먼저 고정하고 데이터 하나만 받는 단항 함수를 얻을 수 있기 때문이다","커링된 함수는 인자의 타입을 자동으로 검사하기 때문이다"],"a":2}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"부분적용과 커링의 차이","q":[{"t":"choice","k":"fp-partial-shape1","q":"3항 함수 f(a, b, c)를 커링한 결과의 호출 형태는?","ex":"커링은 각 단계가 인자 하나만 받도록 완전히 쪼개므로 f(a)(b)(c) 형태가 된다. f(a, b)(c)나 f(a)(b, c)처럼 어딘가에서 두 인자를 한꺼번에 받는 형태는 부분적용에 가깝다. 이 형태 차이가 두 개념을 가르는 기준이다.","o":["f(a, b)(c)","f(a)(b, c)","f(a)(b)(c)","f(a, b, c)"],"a":2},{"t":"choice","k":"fp-partial-multi1","q":"부분적용만의 특징으로 옳은 것은?","ex":"부분적용은 원하는 만큼의 인자를 한꺼번에 채워 넣을 수 있다는 점이 커링과 구별되는 지점이다. 반면 커링은 정의상 한 번에 하나씩만 받는다. 어느 쪽이든 원본 함수는 그대로 남고 새 함수가 만들어진다.","o":["한 번에 여러 개의 인자를 동시에 고정할 수 있다","반드시 인자를 하나씩만 고정할 수 있다","원본 함수를 변경한다","반환값이 항상 원시값이다"],"a":0},{"t":"choice","k":"fp-partial-bind1","q":"아래 코드에서 bind가 수행한 것은 무엇이며 flat(3)의 값은?","ex":"bind는 w와 h를 한 번에 고정해 d만 받는 새 함수를 만들었으므로 부분적용이다. flat(3)은 10 * 2 * 3 = 60을 곧바로 계산해 반환한다. 커링이었다면 인자를 하나씩만 받아 flat(3)이 또 다른 함수를 돌려줬을 것이다.","code":"function volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2);","o":["커링이며 flat(3)은 함수를 반환한다","합성이며 flat(3)은 15다","메모이제이션이며 flat(3)은 10이다","부분적용이며 flat(3)은 60이다"],"a":3},{"t":"input","k":"fp-partial-bindname1","q":"JavaScript에서 인자 일부를 미리 고정해 새 함수를 만들 때 쓰는 Function.prototype의 메서드 이름은? (영어 소문자)","ex":"bind는 this와 앞쪽 인자들을 한 번에 고정한 새 함수를 반환하므로 부분적용의 도구다. 여러 인자를 동시에 고정할 수 있다는 점에서 커링과 구별된다. 화살표 함수로 (...rest) =&gt; f(고정값, ...rest)를 쓰는 것도 같은 효과를 낸다.","a":["bind"]},{"t":"choice","k":"fp-partial-usecase1","q":"부분적용이 특히 유용한 상황은?","ex":"log(level, message)에서 level을 'error'로 고정한 logError를 만들면 호출부가 훨씬 간결해진다. 이렇게 반복되는 설정 인자를 미리 채워 두는 것이 부분적용의 전형적인 쓰임이다. 인자가 매번 달라진다면 고정할 이유가 없다.","o":["모든 인자가 매번 달라지는 함수를 호출할 때","로거의 레벨이나 API의 기본 URL처럼 자주 반복되는 설정 인자를 미리 고정할 때","함수를 클래스 메서드로 바꿔야 할 때","배열의 길이를 줄여야 할 때"],"a":1},{"t":"choice","k":"fp-partial-diff1","q":"커링과 부분적용의 관계로 옳은 것은?","ex":"커링은 함수의 구조를 f(a)(b)(c)라는 단항 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 채워 남은 인자만 받는 새 함수를 만드는 기법이다. 부분적용은 한 번에 여러 인자를 고정할 수 있고 결과가 단항 연쇄일 필요도 없다. 결과가 비슷해 보여 자주 혼동되지만 분명히 다른 개념이다.","o":["둘은 이름만 다른 완전히 같은 개념이다","커링은 단항 함수 연쇄로의 변환이고, 부분적용은 인자 일부를 고정해 더 적은 인자를 받는 함수를 만드는 것으로 서로 다르다","부분적용은 커링의 결과를 되돌리는 연산이다","커링은 인자를 고정하고, 부분적용은 인자를 늘린다"],"a":1}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"Optional / Either와 패턴 매칭","q":[{"t":"choice","k":"fp-adt-map1","q":"Optional의 map이 None에 대해 하는 동작은?","ex":"Optional은 펑터라서 map은 컨테이너 안에 값이 있을 때만 함수를 적용하고 같은 모양의 컨테이너를 돌려준다. None이면 적용을 건너뛰고 None을 그대로 통과시키므로 값이 없는 경우를 매번 검사할 필요가 없다. 덕분에 변환을 안전하게 연결할 수 있다.","o":["함수를 적용해 결과를 Some으로 감싼다","함수를 적용하지 않고 None을 그대로 반환한다","예외를 던진다","null로 변환해 반환한다"],"a":1},{"t":"choice","k":"fp-adt-exh1","q":"패턴 매칭의 완전성(exhaustiveness) 검사가 주는 이점은?","ex":"완전성 검사는 합 타입의 모든 태그를 다뤘는지 컴파일러가 확인해 주는 기능이다. None 처리를 빼먹으면 실행 전에 오류로 알려 주므로 null 참조 버그를 구조적으로 막는다. 나중에 새로운 경우를 추가했을 때 고쳐야 할 지점을 전부 찾아 준다는 점도 큰 이점이다.","o":["실행 속도가 if 문보다 빨라진다","런타임에 예외를 자동으로 잡아 준다","처리하지 않은 경우가 있으면 컴파일 타임에 오류로 알려 준다","합 타입의 경우를 자동으로 하나로 합쳐 준다"],"a":2},{"t":"choice","k":"fp-adt-prod1","q":"곱 타입(product type)에 해당하는 것은?","ex":"곱 타입은 여러 필드를 동시에 모두 갖는 타입으로 레코드와 튜플이 대표적이다. 가능한 값의 수가 각 필드 경우의 수의 곱이 되기 때문에 곱 타입이라 부른다. Either, Optional, 태그된 상태는 여러 경우 중 하나만 성립하는 합 타입이다.","o":["Left 또는 Right 중 하나인 Either","'success' 또는 'error' 중 하나인 상태 태그","Some 또는 None 중 하나인 Optional","{ name: string, age: number } 형태의 레코드"],"a":3},{"t":"choice","k":"fp-adt-sum1","q":"합 타입(sum type)의 예로 옳은 것은?","ex":"합 타입은 여러 경우 중 정확히 하나인 값을 나타내는 태그된 유니온이며 Optional의 Some|None이 대표적이다. 레코드나 튜플처럼 여러 필드를 동시에 갖는 것은 곱 타입이다. 이 둘을 조합해 도메인을 표현하는 것이 대수적 데이터 타입이다.","o":["이름과 나이를 동시에 갖는 레코드","Some 또는 None 중 정확히 하나인 Optional","두 값을 함께 담는 튜플","숫자를 원소로 갖는 배열"],"a":1},{"t":"input","k":"fp-adt-tag1","q":"합 타입의 값이 지금 어떤 경우인지 구분하기 위해 함께 저장하는 표식을 무엇이라 하는가? (한국어 두 글자, 영어로는 tag)","ex":"태그는 { tag: 'some', value: 3 }처럼 그 값이 어느 경우인지 알려 주는 식별자다. 패턴 매칭은 이 태그를 보고 분기하며, 컴파일러도 태그 목록을 근거로 완전성을 검사한다. 그래서 합 타입을 태그된 유니온이라고도 부른다.","a":["태그"]},{"t":"choice","k":"fp-adt-either1","q":"Optional(Maybe)과 Either의 차이로 옳은 것은?","ex":"Optional의 None은 값이 없다는 사실만 알려줄 뿐 왜 없는지는 알려주지 못한다. Either는 Left에 오류 메시지나 오류 객체를 실어 실패의 원인을 전달할 수 있고 Right가 성공을 나타낸다. 둘 다 합 타입이며, 원인을 알려야 할 때 Either를 고른다.","o":["Optional은 실패 이유를 담을 수 없지만 Either는 Left에 실패 이유를 담을 수 있다","Either는 성공만 표현하고 Optional은 실패만 표현한다","Optional은 값을 두 개 담고 Either는 하나만 담는다","Either는 곱 타입이고 Optional은 합 타입이다"],"a":0}],"th":{"sum":"커링은 여러 인자를 받는 함수를 한 번에 인자 하나씩 받는 연쇄로 바꾸는 변환이고, 부분적용은 일부 인자를 미리 고정해 더 적은 인자를 받는 새 함수를 만드는 기법이다. 대수적 데이터 타입과 패턴 매칭은 없을 수 있는 값과 실패를 타입으로 드러내 준다.","body":[{"h":"커링과 부분적용은 다르다","t":"커링은 f(a, b, c)를 f(a)(b)(c)처럼 반드시 한 번에 하나씩 받는 단항 함수의 연쇄로 바꾸는 구조적 변환이다. 부분적용은 f(a, b, c)에서 a와 b를 한꺼번에 고정해 c만 받는 함수를 만드는 것으로, 결과가 단항 연쇄일 필요가 없다. JavaScript의 Function.prototype.bind는 여러 인자를 한 번에 고정할 수 있으므로 부분적용에 해당한다."},{"h":"곱 타입과 합 타입","t":"대수적 데이터 타입은 곱 타입과 합 타입으로 구성된다. 곱 타입은 레코드나 튜플처럼 여러 필드를 동시에 가지는 것이고, 합 타입은 태그된 유니온처럼 여러 경우 중 정확히 하나인 것이다. Optional/Maybe는 Some과 None 중 하나, Either는 실패를 뜻하는 Left와 성공을 뜻하는 Right 중 하나인 합 타입이다."},{"h":"패턴 매칭과 완전성","t":"합 타입의 값은 패턴 매칭으로 각 경우를 나눠 처리하며, 컴파일러는 모든 경우를 다뤘는지 완전성(exhaustiveness)을 검사해 준다. 덕분에 None 처리를 빠뜨린 실수를 실행 전에 잡을 수 있어 null 참조 오류를 구조적으로 막는다. Optional의 map은 None이면 함수를 적용하지 않고 None을 그대로 돌려주는 펑터로 동작한다."}],"code":{"c":"// 커링: 한 번에 인자 하나씩\nconst add = a => b => a + b;\nconsole.log(add(2)(3)); // 5\n\n// 부분적용: 여러 인자를 한 번에 고정\nfunction volume(w, h, d) { return w * h * d; }\nconst flat = volume.bind(null, 10, 2); // w, h 동시 고정\nconsole.log(flat(3)); // 60\n\n// Optional의 map: None이면 그대로 통과\nconst mapOpt = (opt, f) =>\n  opt.tag === 'some' ? { tag: 'some', value: f(opt.value) } : opt;","cap":"커링은 단항 연쇄로의 변환, 부분적용은 인자 고정 — 서로 다른 개념이다."},"key":["커링: f(a,b,c) -> f(a)(b)(c), 부분적용: 인자 일부를 미리 고정","Optional은 값의 부재만, Either는 실패 이유까지 담는다","패턴 매칭의 완전성 검사가 누락된 경우를 컴파일 타임에 잡는다"]}},{"t":"직접 짜 보기 — 인자를 나눠 받고, 경우를 나눠 담기","th":{"sum":"커링은 **인자를 한 번에 다 안 받는 것**이고, ADT 는 **가능한 경우를 타입으로 못 박는 것**이다.","body":[{"h":"부분적용은 설정을 미리 고정한다","t":"`log('ERROR')` 로 수준을 고정한 함수를 만들어 두면, 쓰는 자리에서는 메시지만 넘기면 된다. 같은 인자를 반복해 적는 일이 사라진다."},{"h":"커링은 합성을 쉽게 한다","t":"인자가 하나인 함수끼리는 그냥 이어 붙일 수 있다. 커링해 두면 `map(add(1))` 처럼 바로 넘길 수 있다."},{"h":"합 타입은 '둘 중 하나'","t":"성공이거나 실패, 값이 있거나 없거나. 두 경우를 한 값으로 담고 꺼낼 때 반드시 갈라 보게 하면, '실패인데 값을 읽는' 코드가 아예 안 만들어진다."},{"h":"null 대신 경우를 만든다","t":"`null` 은 '없음' 을 뜻하지만 왜 없는지는 말해 주지 않는다. `{ok:false, error:'…'}` 는 이유까지 담아, 부르는 쪽이 제대로 다루게 만든다."}],"code":{"c":"const add = a => b => a + b;\nconst add1 = add(1);\n[1,2,3].map(add1);      // [2,3,4]\n\n// 합 타입\n{ ok: true,  value: 5 }\n{ ok: false, error: '없음' }","cap":"나눠 받고, 갈라 담는다"},"key":["부분적용은 설정을 고정","커링하면 합성이 쉽다","실패도 값으로 담는다"]},"q":[{"k":"curry2 · 인자를 나눠 받기","cat":"internals","q":"두 인자 함수를 받아 <code>f(a)(b)</code> 로 부를 수 있게 바꾸세요.","src":"function curry2(f) {\n  return (a, b) => f(a, b);\n}\n","sol":"function curry2(f) {\n  return a => b => f(a, b);\n}\n","ex":"두 인자를 한 번에 받으면 `map` 에 바로 넘길 수 없습니다 — `map` 은 인자 하나짜리 함수를 기대하거든요. 나눠 받으면 첫 인자를 고정한 함수가 그대로 하나짜리가 되어 어디든 끼워 넣을 수 있습니다.","t":"code","run":"js","tests":[{"in":"curry2((a,b) => a + b)(1)(2)","out":"3"},{"in":"[1,2,3].map(curry2((a,b) => a + b)(10))","out":"[11,12,13]"},{"in":"curry2((a,b) => a * b)(3)(4)","out":"12"}],"edge":[{"in":"typeof curry2((a,b) => a)(1)","out":"'function'"},{"in":"curry2((a,b) => b)(1)(9)","out":"9"}]},{"k":"tryParse · 실패도 값으로 담기","cat":"internals","q":"문자열을 정수로 읽어 <code>{ok:true, value:n}</code> 또는 <code>{ok:false, error:'정수가 아님'}</code> 을 돌려주세요. 공백뿐이거나 숫자가 아니면 실패입니다.","src":"function tryParse(s) {\n  return { ok: true, value: parseInt(s, 10) };\n}\n","sol":"function tryParse(s) {\n  const t = s.trim();\n  if (t === '' || !/^-?\\d+$/.test(t)) return { ok: false, error: '정수가 아님' };\n  return { ok: true, value: Number(t) };\n}\n","ex":"`parseInt('12abc')` 는 12 를 돌려줍니다 — 앞에서 읽히는 만큼만 읽고 나머지를 버려요. 실패가 성공처럼 보이는 겁니다. 그리고 `parseInt('abc')` 의 NaN 을 `ok:true` 로 감싸면, 부르는 쪽은 그 NaN 을 계산에 그대로 씁니다.","t":"code","run":"js","tests":[{"in":"tryParse('42')","out":"{ok:true, value:42}"},{"in":"tryParse('abc')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('  7 ')","out":"{ok:true, value:7}"}],"edge":[{"in":"tryParse('')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('12abc')","out":"{ok:false, error:'정수가 아님'}"},{"in":"tryParse('-3')","out":"{ok:true, value:-3}"}]},{"k":"mapOk · 성공일 때만 이어 가기","cat":"internals","q":"<code>{ok, value, error}</code> 와 함수를 받아, <b>성공이면</b> 값에 함수를 적용한 새 결과를, <b>실패면 그대로</b> 돌려주세요.","src":"function mapOk(r, f) {\n  return { ...r, value: f(r.value) };\n}\n","sol":"function mapOk(r, f) {\n  if (!r.ok) return r;\n  return { ok: true, value: f(r.value) };\n}\n","ex":"실패한 결과에도 함수를 적용하면 `undefined` 가 계산에 들어가거나 그 자리에서 터집니다. 실패를 만나면 더 진행하지 않고 그대로 흘려보내는 것 — 그게 합 타입을 쓰는 이유예요. 오류 처리가 흐름에서 자연히 빠집니다.","t":"code","run":"js","tests":[{"in":"mapOk({ok:true, value:2}, x => x * 10)","out":"{ok:true, value:20}"},{"in":"mapOk({ok:false, error:'없음'}, x => x * 10)","out":"{ok:false, error:'없음'}"},{"in":"mapOk({ok:true, value:0}, x => x + 1)","out":"{ok:true, value:1}"}],"edge":[{"in":"mapOk({ok:false, error:'e'}, () => { throw new Error('불려선 안 됨'); })","out":"{ok:false, error:'e'}"},{"in":"mapOk({ok:true, value:'a'}, s => s + 'b')","out":"{ok:true, value:'ab'}"}]}]}]},{"t":"시뮬레이션 · 눈으로 보는 코드","l":[{"t":"시뮬레이션 I","q":[{"t":"sim","k":"메모리 시각화","lv":2,"q":"불변 갱신을 만드세요. 원본을 건드리지 않고 <b>새 객체를 만들어</b> 값을 바꿉니다. <b>단계마다</b> <code>snap(라벨, {원본:base, 결과:cur, 같은객체:base===cur})</code> 를 부르세요. 반환값은 <code>{원본유지, 결과}</code> 입니다.","src":"const base = { name: '가', tags: ['a'] };\n\nfunction update(obj, key, value) {\n  // 여기에 구현하세요 — 원본을 바꾸지 않고 새 객체를 돌려줍니다\n  return obj;\n}\n\nconst next = update(base, 'name', '나');\nRESULT = { 원본유지: base.name === '가', 결과: next.name };","tests":[{"d":"원본이 그대로다","js":"RESULT.원본유지===true"},{"d":"새 값이 반영된다","js":"RESULT.결과==='나'"},{"d":"장면이 남았다","js":"FRAMES.length>=1"},{"d":"결과는 원본과 다른 객체다","js":"FRAMES[0].value['같은객체']===false"},{"d":"장면 속 원본의 이름이 바뀌지 않았다","js":"FRAMES[0].value['원본'].name==='가'"}],"ex":"불변 갱신의 값어치는 '<b>바뀌었는지 참조 비교 하나로 안다</b>' 는 데 있습니다. 원본을 제자리에서 고치면 이전 값이 사라져 무엇이 달라졌는지 알 수 없지만, 새 객체를 만들면 <code>prev !== next</code> 하나로 판단할 수 있습니다. React 의 리렌더 판단, 되돌리기 기능, 시간 여행 디버깅이 전부 이 성질 위에 서 있습니다. 대신 전개 연산자는 <b>얕은</b> 복사라 중첩 객체는 그 층까지 새로 만들어야 합니다."},{"t":"sim","k":"실행 순서 시각화","lv":2,"q":"함수 합성 <code>compose(f, g)(x) = f(g(x))</code> 를 만드세요. <b>각 함수가 실행될 때마다</b> <code>snap(\"적용 \"+이름, {값:v})</code> 를 부르세요. 반환값은 최종 결과입니다.","src":"function compose(...fns) {\n  // 여기에 구현하세요 — 오른쪽부터 적용합니다\n}\n\nconst inc = x => { snap('적용 inc', { 값: x + 1 }); return x + 1; };\nconst dbl = x => { snap('적용 dbl', { 값: x * 2 }); return x * 2; };\nRESULT = compose(inc, dbl)(5);","tests":[{"d":"결과가 11 이다 (5×2 그다음 +1)","js":"RESULT===11"},{"d":"두 함수가 모두 실행됐다","js":"FRAMES.length===2"},{"d":"오른쪽 함수가 먼저 적용된다","js":"FRAMES[0].label==='적용 dbl'"},{"d":"중간 값이 10 이다","js":"FRAMES[0].value['값']===10"},{"d":"마지막 값이 결과와 같다","js":"FRAMES[1].value['값']===RESULT"}],"ex":"<code>compose(f, g)</code> 는 수학의 <code>f∘g</code> 와 같아 <b>오른쪽부터</b> 적용합니다. 왼쪽부터 읽고 싶으면 <code>pipe</code> 를 쓰는데, 둘을 헷갈려 순서가 뒤집히는 것이 합성에서 가장 흔한 실수입니다. <code>reduceRight</code> 한 줄로 구현되는 데서 보이듯, 합성은 특별한 기능이 아니라 <b>함수를 값처럼 다루면 자연히 따라오는</b> 것입니다."},{"t":"sim","k":"실행 순서 시각화","lv":3,"q":"커링을 만드세요. <code>curry(f)</code> 는 인자가 다 모일 때까지 <b>함수를 돌려주고</b>, 다 모이면 실행합니다. <b>인자를 받을 때마다</b> <code>snap(\"인자 \"+n, {모인인자:[...args]})</code> 를 부르세요. 반환값은 최종 계산 결과입니다.","src":"function curry(fn) {\n  // 여기에 구현하세요 — fn.length 만큼 모이면 실행합니다\n}\n\nconst add3 = (a, b, c) => a + b + c;\nconst c = curry(add3);\nRESULT = c(1)(2)(3);","tests":[{"d":"결과가 6 이다","js":"RESULT===6"},{"d":"세 번에 걸쳐 인자를 받는다","js":"FRAMES.length===3"},{"d":"인자가 하나씩 쌓인다","js":"JSON.stringify(FRAMES.map(f=>f.value['모인인자'].length))==='[1,2,3]'"},{"d":"마지막에 인자가 셋이다","js":"JSON.stringify(FRAMES[2].value['모인인자'])==='[1,2,3]'"},{"d":"앞 단계는 아직 계산하지 않는다","js":"FRAMES[0].value['모인인자'].length===1"}],"ex":"커링은 '<b>인자를 나눠 받는 것</b>' 이고, 그 값어치는 <b>부분 적용</b>에 있습니다. <code>add(1)</code> 을 변수에 담아 두면 '1을 더하는 함수' 가 되어 재사용됩니다. 구현의 핵심은 <code>fn.length</code> — 자바스크립트 함수는 자기가 몇 개를 받는지 알고 있습니다. 다만 기본값이나 나머지 매개변수가 있으면 <code>length</code> 가 줄어들어 커링이 일찍 실행되므로, 라이브러리들은 개수를 직접 받는 형태도 함께 제공합니다."},{"t":"sim","k":"상태 시각화","lv":3,"q":"게으른 평가를 만드세요. <code>lazy(fn)</code> 은 <b>처음 값을 요구할 때만</b> 계산하고 그 뒤로는 기억해 둔 값을 돌려줍니다. <b>계산·재사용마다</b> <code>snap(라벨, {계산횟수:n})</code> 을 부르세요. 반환값은 실제 계산 횟수입니다.","src":"function lazy(fn) {\n  // 여기에 구현하세요 — 처음 한 번만 계산하고 기억합니다\n}\n\nlet calls = 0;\nconst v = lazy(() => { calls++; snap('계산', { 계산횟수: calls }); return 42; });\nv(); v(); v();\nRESULT = calls;","tests":[{"d":"세 번 불러도 한 번만 계산한다","js":"RESULT===1"},{"d":"계산 장면이 한 번뿐이다","js":"FRAMES.filter(f=>f.label==='계산').length===1"},{"d":"재사용 장면이 두 번이다","js":"FRAMES.filter(f=>f.label==='재사용').length===2"},{"d":"계산이 재사용보다 먼저다","js":"FRAMES[0].label==='계산'"},{"d":"장면이 3개다","js":"FRAMES.length===3"}],"ex":"게으른 평가는 <b>필요하기 전에는 계산하지 않는다</b>는 원칙입니다. 비싼 설정값·큰 파일·네트워크 호출을 미리 하지 않으므로 시작이 빨라지고, 끝내 안 쓰이면 아예 계산되지 않습니다. 여기에 <b>메모이제이션</b>이 붙어 두 번째부터는 공짜입니다. 주의할 것은 <code>fn</code> 이 부수효과를 가지면 '언제 실행되는지' 가 예측하기 어려워진다는 점입니다 — 그래서 게으름과 순수 함수는 짝으로 다닙니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}},{"t":"시뮬레이션 II","q":[{"t":"sim","k":"알고리즘 시각화","lv":2,"q":"<code>reduce</code> 로 <code>map</code> 과 <code>filter</code> 를 만드세요. <b>누적값이 자랄 때마다</b> <code>snap(라벨, [...acc])</code> 를 부르세요. 반환값은 <code>{mapped, filtered}</code> 입니다.","src":"function myMap(arr, f) {\n  // reduce 로 구현하세요\n  return [];\n}\nfunction myFilter(arr, p) {\n  // reduce 로 구현하세요\n  return [];\n}\n\nRESULT = { mapped: myMap([1,2,3], x => x * 2), filtered: myFilter([1,2,3,4], x => x % 2 === 0) };","tests":[{"d":"map 결과가 맞다","js":"JSON.stringify(RESULT.mapped)==='[2,4,6]'"},{"d":"filter 결과가 맞다","js":"JSON.stringify(RESULT.filtered)==='[2,4]'"},{"d":"map 장면이 3개다","js":"FRAMES.filter(f=>f.label==='map').length===3"},{"d":"filter 는 4번 돌지만 결과는 2개만 자란다","js":"(function(){var f=FRAMES.filter(x=>x.label==='filter');return f.length===4&&f[3].value.length===2;})()"},{"d":"누적값은 줄어들지 않는다","js":"(function(){var f=FRAMES.filter(x=>x.label==='filter');for(var i=1;i<f.length;i++) if(f[i].value.length<f[i-1].value.length) return false; return true;})()"}],"ex":"<code>reduce</code> 는 '<b>접기</b>' 이고, map·filter 는 그 특수한 경우입니다. map 은 매번 하나를 넣는 접기, filter 는 조건에 맞을 때만 넣는 접기입니다. 이걸 알면 두 번 훑던 <code>arr.map(f).filter(p)</code> 를 한 번의 reduce 로 합칠 수 있습니다. 장면에서 filter 가 4번 돌지만 누적값은 2번만 자라는 것이 '<b>순회 횟수와 결과 크기는 다르다</b>' 를 보여 줍니다."}],"th":{"sum":"코드를 쓰고 무슨 일이 일어나는지 눈으로 확인하는 훈련입니다. snap(라벨, 값) 을 부르면 그 순간이 한 장면으로 남고, 슬라이더로 되감아 볼 수 있습니다.","body":[{"h":"설명 대신 장면으로 이해한다","t":"'버블 정렬은 O(n²)' 이라는 문장보다, 교환 장면이 <b>몇 개나 쌓이는지</b> 보는 편이 빠릅니다. 이진 탐색에서 흐릿해지는 칸이 절반씩 늘어나는 것도 마찬가지입니다."},{"h":"기록은 사본으로 남긴다","t":"<code>snap(\"단계\", arr)</code> 는 그 순간의 값을 복사해 둡니다. 배열을 그대로 넘겨도 되지만, 스택처럼 계속 바뀌는 것은 <code>[...stack]</code> 으로 넘겨야 나중에 뒤섞이지 않습니다."},{"h":"강조로 '지금 보는 곳' 을 표시한다","t":"세 번째 인자로 <code>{hi:[i,j]}</code> 를 주면 그 칸이 빨갛게, <code>{dim:[...]}</code> 를 주면 흐리게 그려집니다. 알고리즘이 <b>어디를 보고 있는지</b>가 드러납니다."},{"h":"채점은 결과 + 흐름","t":"반환값만 맞추면 되는 게 아니라 <b>장면의 흐름</b>도 봅니다 — 창이 한 칸씩 움직였는가, 메모 표가 한 칸씩 커졌는가. 우연히 맞은 답과 제대로 만든 답이 갈립니다."}],"code":{"t":"한 줄이면 장면이 남는다","c":"if (a[j] > a[j+1]) {\n  [a[j], a[j+1]] = [a[j+1], a[j]];\n  snap(\"교환\", a, { hi: [j, j+1] });   // ← 이 순간이 기록된다\n}"},"key":["snap(라벨, 값, 옵션) 으로 순간을 남긴다","계속 바뀌는 값은 사본으로 넘긴다","hi·dim 으로 보고 있는 위치를 표시한다","채점은 결과값과 장면의 흐름을 함께 본다"]}}]},{"t":"실행형 실전 — 함수를 값으로 다룬다","l":[{"t":"커링·불변 갱신·지연 평가","xp":80,"th":{"sum":"함수형의 도구는 셋 다 '나중에'를 다룬다 — **인자를 나중에**(커링), **복사를 최소로**(구조 공유), **계산을 한 번만**(지연).","body":[{"h":"모으고, 공유하고","t":"커링은 인자를 **새 배열로** 모아 두다가 fn.length 에 이르면 발사한다. 새 배열이라야 부분 적용을 재사용해도 서로 오염되지 않는다. 불변 갱신은 경로 위만 복사하고 나머지 가지는 **참조를 공유**한다 — React 가 === 만으로 변경을 감지하는 근거다."},{"h":"실행 여부는 값과 다른 정보다","t":"한 번만 계산하는 lazy 는 '실행했는가' 를 **플래그로 따로** 기억해야 한다. 결과값으로 판단하면 undefined·null 을 돌려주는 함수에서 매번 다시 실행된다 — 캐시에서 null 을 '없음' 으로 쓰다 겪는 사고와 같은 뿌리다."}],"code":{"c":"// 값이 아니라 플래그로 판단한다\nlet done = false, value;\nif (!done) { value = fn(); done = true; }","cap":"undefined 반환도 '한 번 실행됨' 이다"},"key":["커링은 concat 으로 새 배열 — 재사용 안전","불변 갱신은 경로 위만 복사(구조 공유)","n.z===o.z 가 리렌더 생략의 근거","실행 여부 플래그와 결과값을 분리"]},"q":[{"t":"code","run":"js","k":"커링","cat":"internals","q":"<b>커링</b>을 구현하세요. <code>curry(fn)</code> 은 인자를 나눠 받을 수 있는 함수를 돌려줍니다. 호출마다 인자를 <b>모으고</b>, 모인 개수가 <code>fn.length</code> 에 이르면 원함수를 호출합니다. <code>f(1)(2)(3)</code> 도 <code>f(1,2)(3)</code> 도 같아야 하고, <b>부분 적용을 재사용해도</b> 서로 영향이 없어야 합니다.","src":"function curry(fn) {\n  // TODO: fn.length 만큼 모이면 호출\n  return fn;\n}","sol":"function curry(fn) {\n  const step = (args) => (...next) => {\n    const all = args.concat(next);\n    return all.length >= fn.length ? fn(...all) : step(all);\n  };\n  return step([]);\n}","tests":[{"in":"curry((a,b,c)=>a+b+c)(1)(2)(3)","out":"6"},{"in":"curry((a,b,c)=>a+b+c)(1,2)(3)","out":"6"},{"in":"curry((a,b)=>a*b)(4,5)","out":"20"},{"in":"(() => { const add=curry((a,b)=>a+b); const add1=add(1); return [add1(2), add1(10)]; })()","out":"[3,11]"}],"edge":[{"in":"curry((a)=>a*2)(7)","out":"14"},{"in":"curry((a,b,c)=>a+b+c)(1)(2,3)","out":"6"}],"ex":"🎯 커링의 핵심은 <b>인자를 배열로 모아 두었다가</b> 충분해지면 원함수를 부르는 것입니다. <code>fn.length</code>(선언된 매개변수 수)가 '충분함' 의 기준입니다.\n💡 <code>args.concat(next)</code> 로 <b>새 배열</b>을 만드는 것이 재사용의 비결입니다. <code>add1 = add(1)</code> 을 여러 번 호출해도 각 호출이 자기 배열을 갖기 때문에 서로를 오염시키지 않습니다 — push 로 공유 배열에 쌓으면 두 번째 호출부터 틀어집니다.\n⚠️ <code>fn.length</code> 는 기본값·나머지 매개변수를 <b>세지 않습니다</b>. <code>(a, b = 1) => …</code> 의 length 는 1이라 커링이 일찍 발사됩니다.\n🔧 커링은 '설정을 먼저, 데이터를 나중에' 받는 API 를 만들 때 빛납니다. <code>log('error')</code> 처럼 부분 적용해 두고 재사용하는 패턴이 대표적입니다."},{"t":"code","run":"js","k":"불변 갱신과 구조 공유","cat":"internals","q":"중첩 객체를 <b>불변으로 갱신</b>하는 <code>setIn(obj, path, value)</code> 를 구현하세요. 원본은 그대로 두고, <b>경로 위의 객체만 복사</b>하고 <b>경로 밖의 가지는 그대로 공유</b>합니다(구조 공유). 빈 경로면 <code>value</code> 자체를, 중간 경로가 없으면 만들어 가며 넣으세요.","src":"function setIn(obj, path, value) {\n  // TODO: 경로 위만 복사\n  return obj;\n}","sol":"function setIn(obj, path, value) {\n  if (path.length === 0) return value;\n  const [head, ...rest] = path;\n  const base = obj && typeof obj === 'object' ? obj : {};\n  return Object.assign({}, base, { [head]: setIn(base[head], rest, value) });\n}","tests":[{"in":"setIn({a:{b:1},z:{c:2}},['a','b'],9)","out":"{a:{b:9},z:{c:2}}"},{"in":"(() => { const o={a:{b:1},z:{c:2}}; const n2=setIn(o,['a','b'],9); return n2.z===o.z; })()","out":"true"},{"in":"(() => { const o={a:{b:1}}; setIn(o,['a','b'],9); return o.a.b; })()","out":"1"},{"in":"(() => { const o={a:{b:1}}; const n2=setIn(o,['a','b'],9); return n2.a===o.a; })()","out":"false"}],"edge":[{"in":"setIn({x:1},[],5)","out":"5"},{"in":"setIn({},['a','b'],1)","out":"{a:{b:1}}"}],"ex":"🎯 불변 갱신은 '전부 복사' 가 아닙니다. <b>바뀐 경로 위의 객체만</b> 새로 만들고 나머지 가지는 <b>참조를 그대로 공유</b>합니다 — 그래서 깊은 트리도 갱신 비용이 경로 길이에 비례합니다.\n💡 <code>n.z === o.z</code> 가 true 인 것이 핵심 테스트입니다. React 가 <code>===</code> 비교만으로 '이 가지는 안 바뀌었으니 리렌더 생략' 을 판단할 수 있는 근거가 바로 이 구조 공유입니다.\n⚠️ <code>obj.a.b = 9</code> 로 직접 고치면 참조가 안 바뀌어 React·Redux 가 <b>변경을 감지하지 못합니다</b>. 반대로 <code>JSON.parse(JSON.stringify(o))</code> 전체 복사는 감지는 되지만 모든 가지가 새 참조라 <b>모든 곳이 리렌더</b>됩니다.\n🔧 Immer 는 이 패턴을 Proxy 로 자동화한 것이고, <code>structuredClone</code> 은 공유 없는 전체 복사입니다 — 셋의 차이를 알고 골라 써야 합니다."},{"t":"code","run":"js","k":"지연 평가와 메모이즈","cat":"internals","q":"<b>한 번만 계산하는 지연 값</b> <code>lazy(fn)</code> 을 구현하세요. 돌려준 함수를 처음 부를 때만 <code>fn</code> 을 실행해 결과를 기억하고, 이후엔 기억한 값을 돌려줍니다. <b><code>fn</code> 이 <code>undefined</code> 를 돌려줘도 다시 실행하면 안 됩니다</b> — 값이 아니라 <b>실행 여부 플래그</b>로 판단하세요.","src":"function lazy(fn) {\n  let value;\n  return () => {\n    if (value === undefined) value = fn();\n    return value;\n  };\n}","sol":"function lazy(fn) {\n  let done = false, value;\n  return () => {\n    if (!done) { value = fn(); done = true; }\n    return value;\n  };\n}","tests":[{"in":"(() => { let n2=0; const f=lazy(()=>{n2++; return 42;}); f(); f(); return [n2, f()]; })()","out":"[1,42]"},{"in":"(() => { let n2=0; const f=lazy(()=>{n2++;}); f(); f(); return n2; })()","out":"1"},{"in":"(() => { let n2=0; lazy(()=>{n2++;}); return n2; })()","out":"0"},{"in":"lazy(()=>'x')()","out":"'x'"}],"edge":[{"in":"(() => { let n2=0; const f=lazy(()=>{n2++; return null;}); return [f(), f(), n2]; })()","out":"[null,null,1]"},{"in":"(() => { let n2=0; const mk=()=>lazy(()=>++n2); const f=mk(), g=mk(); return [f(), g(), f()]; })()","out":"[1,2,1]"}],"ex":"🎯 시작 코드는 그럴듯하지만 <b>값으로 실행 여부를 판단하는</b> 버그가 있습니다. <code>fn</code> 이 <code>undefined</code> 를 돌려주면 '아직 실행 안 함' 과 구별이 안 되어 <b>매번 다시 실행</b>됩니다.\n💡 그래서 <code>done</code> 플래그를 <b>따로</b> 둡니다. '실행했는가' 와 '결과가 무엇인가' 는 다른 정보이고, 하나의 변수에 욱여넣으면 특정 값에서 무너집니다 — 캐시에서 <code>null</code> 을 '없음' 으로 쓰다 당하는 사고와 같은 뿌리입니다.\n⚠️ 부수효과가 있는 <code>fn</code> 이면 이 버그는 <b>이중 과금·중복 요청</b>이 됩니다. 테스트의 <code>n2</code> 카운터가 그 시나리오를 흉내 낸 것입니다.\n🔧 이 패턴이 곧 싱글턴 초기화·<code>lazy val</code>·React 의 <code>useMemo</code> 입니다. 다인자 버전이 메모이제이션(인자를 키로 한 결과 캐시)입니다."}]}]}]);
